pub fn deferredStatementId(keyword: frontend.Keyword) []const u8 {
    return switch (keyword) {
        .error_ => "QB45-P2-050",
        .shared => "QB45-P2-153",
        .static => "QB45-P2-161",
        else => "QB45-P2-UNMAPPED",
    };
}
